import{boot,e,field,editAttrs}from'../creative-kit/ui.js?v=0.22.0';import{make,validate,apply,markdown,ROUTES,SIDE_FIELDS,PLAN_FIELDS}from'./state.js?v=0.21.0';
const labels={proposal:'What is the proposal?',benefit:'What benefit does it protect?',context:'When is this a reasonable choice?',cost:'What cost does it accept?',evidence:'What evidence would change this view?'};
const prompts={context:'Where could each proposal be the right choice? Define the boundary between those contexts.',sequence:'Could one approach prepare for, trigger or follow the other? Name the transition.',invent:'What different mechanism could protect both benefits? It need not split the difference.'};
function render(w){return `<section class="proposal-pair">${Object.entries(w.sides).map(([side,s])=>`<article class="panel proposal ${side}"><div class="card-top"><span>Proposal ${side.toUpperCase()}</span><button class="text-button" data-action="edit-side" data-side="${side}">Edit position</button></div><h2>${e(s.proposal||'Describe a reasonable proposal')}</h2><div class="benefit" data-drag-id="${side}"><div class="card-top"><span>BENEFIT TO PROTECT</span><button class="drag-handle" data-drag-handle data-action="benefit-menu" data-side="${side}" aria-label="Use benefit ${side.toUpperCase()} in an alternative">⠿</button></div><p>${e(s.benefit||'Name what this position protects.')}</p><button class="text-button" data-action="benefit-menu" data-side="${side}">Use this benefit ↗</button></div><dl><dt>REASONABLE WHEN</dt><dd>${e(s.context||'Which situation does it assume?')}</dd><dt>ACCEPTED COST</dt><dd>${e(s.cost||'What is sacrificed?')}</dd><dt>COULD CHANGE WITH</dt><dd>${e(s.evidence||'What evidence matters?')}</dd></dl></article>`).join('')}</section><div class="section-head"><div><h2>Work on the tension, not the winner.</h2><p>Drag a benefit into an alternative, or use its button. Naming both benefits is a design intention; explain how the mechanism would protect them.</p></div></div><div class="synthesis-grid">${w.plans.map(p=>`<section class="panel synthesis ${w.selected===p.id?'chosen':''}" data-drop-id="${e(p.id)}"><div class="card-top"><span>${ROUTES[p.route]}</span>${w.selected===p.id?'<span class="tag">To test</span>':''}</div><h2>${e(p.title)}</h2><p class="route-prompt">${prompts[p.route]}</p><div class="benefit-links">${p.protects.map(s=>`<button class="benefit-link ${s}" data-action="unprotect" data-id="${e(p.id)}" data-side="${s}"><strong>${s.toUpperCase()}</strong> ${e(w.sides[s].benefit||'Unnamed benefit')} ×</button>`).join('')||'<span class="empty">Drop the benefits this should preserve.</span>'}</div>${p.stale?'<p class="recheck">A linked position changed. Revisit this design.</p>':''}<p class="mechanism">${e(p.mechanism||'Describe how this would work.')}</p>${p.test?`<div class="test-preview"><span>SMALLEST TEST</span><p>${e(p.test)}</p></div>`:''}<div class="card-actions"><button data-action="develop" data-id="${e(p.id)}">Develop</button><button class="text-button" data-action="fork" data-id="${e(p.id)}">Fork</button><button class="text-button" data-action="select" data-id="${e(p.id)}" aria-pressed="${w.selected===p.id}">${w.selected===p.id?'✓ Selected':'Select a test'}</button></div></section>`).join('')}</div><p class="hint">Selecting a test keeps the other alternatives. An unresolved disagreement may reveal different contexts or values that should stay explicit.</p>`;}
function editSide(side,k){const s=k.w().sides[side];k.open(SIDE_FIELDS.map(f=>field(`side-${f}`,labels[f],s[f],editAttrs('sides',side,f))).join('')+'<button class="primary" data-action="close">Done</button>',`Proposal ${side.toUpperCase()}`);}
function develop(id,k){const p=k.w().plans.find(p=>p.id===id);const l={title:'Alternative name',mechanism:'How would this protect the benefits?',boundary:'Which conditions or transition need to be explicit?',cost:'What does this approach still sacrifice?',test:'The smallest useful test',learn:'What result would make you change your mind?'};k.open(`<p>${prompts[p.route]}</p>`+PLAN_FIELDS.map(f=>field(`plan-${f}`,l[f],p[f],editAttrs('plans',id,f))).join('')+`<div class="toolbar"><button class="primary" data-action="review" data-id="${e(id)}">Benefit fit checked</button><button data-action="close">Done</button><button class="delete" data-action="remove" data-id="${e(id)}">Remove alternative</button></div>`,'Develop a third way');}
await boot({route:'disagreement',code:'S12',title:'Productive disagreement',description:'Keep two reasonable positions visible. Find the benefits, contexts and costs beneath them.',make,validate,apply,markdown,render,drop:(side,id,k)=>k.act({type:'protect',id,side}),handle:(a,d,k)=>{if(a==='edit-side')editSide(d.side,k);else if(a==='develop')develop(d.id,k);else if(a==='benefit-menu')k.open('<p>Link this benefit to an alternative. It can inform more than one.</p><div class="dialog-options">'+k.w().plans.map(p=>`<button data-action="protect" data-id="${e(p.id)}" data-side="${d.side}">${e(p.title)}</button>`).join('')+'</div>','Protect a benefit');else if(a==='protect'){k.close();k.act({type:a,id:d.id,side:d.side});}else if(a==='fork'){const id=k.uid();if(k.act({type:a,id,parent:d.id}))develop(id,k);}else if(['review','remove'].includes(a)){k.close();k.act({type:a,id:d.id});}else if(['select','unprotect'].includes(a))k.act({type:a,id:d.id,side:d.side});}});
